// fixture is one entry of testdata/requests.json, generated by running
// app.js buildRequestFromForm (testdata/gen-fixtures.cjs) against the
// embedded catalog.
type fixture struct {
	Target  string          `json:"target"`
	Desktop string          `json:"desktop"`
	Request json.RawMessage `json:"request"`
}

func loadFixtures(t *testing.T) []fixture {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("testdata", "requests.json"))
	if err != nil {
		t.Fatal(err)
	}
	var fs []fixture
	if err := json.Unmarshal(b, &fs); err != nil {
		t.Fatal(err)
	}
	if len(fs) < 3 {
		t.Fatalf("only %d fixtures", len(fs))
	}
	return fs
}

func generic(t *testing.T, b []byte) any {
	t.Helper()
	var v any
	if err := json.Unmarshal(b, &v); err != nil {
		t.Fatal(err)
	}
	return v
}

// The helper's request for a catalog target is byte-for-byte what app.js
// produces for the same guided-picker selection (key order included).
func TestParityWithAppJS(t *testing.T) {
	c, err := catalog.EmbeddedCatalog()
	if err != nil {
		t.Fatal(err)
	}
	qualified := 0
	for _, f := range loadFixtures(t) {
		t.Run(f.Target, func(t *testing.T) {
			tg, ok := c.Lookup(f.Target)
			if !ok {
				t.Fatalf("fixture target not in catalog model")
			}
			if tg.Desktop != f.Desktop {
				t.Fatalf("desktop %q, fixture %q", tg.Desktop, f.Desktop)
			}
			ids, err := FlatpakChoice(c, tg.Desktop, "default")
			if err != nil {
				t.Fatal(err)
			}
			req, _, err := FromTarget(c, f.Target, ids)
			if err != nil {
				t.Fatal(err)
			}
			got, _ := json.Marshal(req)
			var want bytes.Buffer
			if err := json.Compact(&want, f.Request); err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(got, want.Bytes()) {
				t.Fatalf("request differs from app.js\n got: %s\nwant: %s", got, want.Bytes())
			}
			if req.QualificationID != "" {
				qualified++
			}
		})
	}
	if qualified == 0 {
		t.Fatal("no fixture exercises a qualified target")
	}
}

// Native changes the browser relay to ghcr.io and nothing else.
func TestNativeOnlySwapsRelay(t *testing.T) {
	for _, f := range loadFixtures(t) {
		out, err := Native(f.Request)
		if err != nil {
			t.Fatal(err)
		}
		got := generic(t, out).(map[string]any)
		want := generic(t, f.Request).(map[string]any)
		if want["registry"] != DefaultRelay || got["registry"] != DirectRegistry {
			t.Fatalf("registry %v -> %v", want["registry"], got["registry"])
		}
		delete(got, "registry")
		delete(want, "registry")
		if !reflect.DeepEqual(got, want) {
			t.Fatalf("Native changed more than the registry:\n%s", out)
		}
	}
	custom := []byte(`{"schemaVersion":1,"kind":"build-request","customImage":true,"image":"quay.io/x/y:z","registry":"https://quay.io"}`)
	out, _ := Native(custom)
	if !strings.Contains(string(out), `"registry": "https://quay.io"`) {
		t.Fatalf("custom registry rewritten: %s", out)
	}
}

func TestFlatpakChoice(t *testing.T) {
	c, err := catalog.EmbeddedCatalog()
	if err != nil {
		t.Fatal(err)
	}
	if ids, _ := FlatpakChoice(c, "gnome", "none"); len(ids) != 0 || ids == nil {
		t.Fatalf("none: %#v", ids)
	}
	ids, err := FlatpakChoice(c, "gnome", " org.mozilla.firefox, org.gnome.Maps,org.mozilla.firefox ")
	if err != nil || !reflect.DeepEqual(ids, []string{"org.mozilla.firefox", "org.gnome.Maps"}) {
		t.Fatalf("list: %v %v", ids, err)
	}
	if _, err := FlatpakChoice(c, "gnome", "org.mozilla.firefox,rm -rf"); err == nil {
		t.Fatal("invalid ID accepted")
	}
	def, _ := FlatpakChoice(c, "gnome", "default")
	if len(def) == 0 {
		t.Fatal("no default flatpaks for gnome")
	}
}

func TestLoadFileAndSetFlatpaks(t *testing.T) {
	f := loadFixtures(t)[0]
	p := filepath.Join(t.TempDir(), "build-request.json")
	if err := os.WriteFile(p, f.Request, 0o644); err != nil {
		t.Fatal(err)
	}
	raw, r, err := LoadFile(p)
	if err != nil || r.Target == nil || r.Image == "" {
		t.Fatalf("LoadFile: %v %+v", err, r)
	}
	out, err := SetFlatpaks(raw, []string{"org.gnome.Maps"})
	if err != nil {
		t.Fatal(err)
	}
	m := generic(t, out).(map[string]any)
	if fp := m["options"].(map[string]any)["flatpaks"].([]any); len(fp) != 1 || fp[0] != "org.gnome.Maps" {
		t.Fatalf("flatpaks %v", fp)
	}
	for name, doc := range map[string]string{
		"wrong kind":   `{"schemaVersion":1,"kind":"other","image":"a/b:c"}`,
		"wrong schema": `{"schemaVersion":2,"kind":"build-request","image":"a/b:c"}`,
		"no image":     `{"schemaVersion":1,"kind":"build-request"}`,
		"not json":     `{`,
	} {
		_ = os.WriteFile(p, []byte(doc), 0o644)
		if _, _, err := LoadFile(p); err == nil {
			t.Errorf("%s accepted", name)
		}
	}
}

// The tacklebox pin must equal native/go.mod's: the engine shipped with the
// Media Writer is the one the website and the Fyne app use.
func TestTackleboxPinMatchesNative(t *testing.T) {
	pin := func(path string) string {
		b, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
		}
		for _, line := range strings.Split(string(b), "\n") {
			f := strings.Fields(line)
			for i := 0; i+1 < len(f); i++ {
				if f[i] == "github.com/tuna-os/tacklebox" {
					return f[i+1]
				}
			}
		}
		t.Fatalf("no tacklebox requirement in %s", path)
		return ""
	}
	helper, native := pin("../../go.mod"), pin("../../../../native/go.mod")
	if helper != native {
		t.Fatalf("desktop/helper pins tacklebox %s, native/ pins %s", helper, native)
	}
}
